    always_comb begin
        rd_coef8 = 32'h0;
        rd_coef8[11:0] = coef8_value_o;
    end
    logic [31:0] rd_coef9;
    always_comb begin
        rd_coef9 = 32'h0;
        rd_coef9[11:0] = coef9_value_o;
    end
    logic [31:0] rd_coef10;
    always_comb begin
        rd_coef10 = 32'h0;
        rd_coef10[11:0] = coef10_value_o;
    end
    logic [31:0] rd_coef11;
    always_comb begin
        rd_coef11 = 32'h0;
        rd_coef11[11:0] = coef11_value_o;
    end
    logic [31:0] rd_coef12;
    always_comb begin
        rd_coef12 = 32'h0;
        rd_coef12[11:0] = coef12_value_o;
    end
    logic [31:0] rd_coef13;
    always_comb begin
        rd_coef13 = 32'h0;
        rd_coef13[11:0] = coef13_value_o;
    end
    logic [31:0] rd_coef14;
    always_comb begin
        rd_coef14 = 32'h0;
        rd_coef14[11:0] = coef14_value_o;
    end
    logic [31:0] rd_coef15;
    always_comb begin
        rd_coef15 = 32'h0;
        rd_coef15[11:0] = coef15_value_o;
    end
    logic [31:0] rd_scratch;
    always_comb begin
        rd_scratch = 32'h0;
        rd_scratch[31:0] = scratch_value_o;
    end
    logic [31:0] rd_err_addr;
    always_comb begin
        rd_err_addr = 32'h0;
        rd_err_addr[11:0] = ecap_addr;
    end
    logic [31:0] rd_err_status;
    always_comb begin
        rd_err_status = 32'h0;
        rd_err_status[0:0] = ecap_sticky;
        rd_err_status[1:1] = ecap_is_write;
        rd_err_status[15:8] = ecap_count;
    end
    logic [31:0] rd_value;
    logic        rd_hit;
    always_comb begin
        rd_hit = 1'b1;
        case (s_axil_araddr[11:2])
            ADDR_ID: rd_value = rd_id;
            ADDR_CTRL: rd_value = rd_ctrl;
            ADDR_CMD: rd_value = rd_cmd;
            ADDR_STATUS: rd_value = rd_status;
            ADDR_JOB_CYCLES: rd_value = rd_job_cycles;
            ADDR_IN_BEATS: rd_value = rd_in_beats;
            ADDR_OUT_BEATS: rd_value = rd_out_beats;
            ADDR_COEF0: rd_value = rd_coef0;
            ADDR_COEF1: rd_value = rd_coef1;
            ADDR_COEF2: rd_value = rd_coef2;
            ADDR_COEF3: rd_value = rd_coef3;
            ADDR_COEF4: rd_value = rd_coef4;
            ADDR_COEF5: rd_value = rd_coef5;
            ADDR_COEF6: rd_value = rd_coef6;
            ADDR_COEF7: rd_value = rd_coef7;
            ADDR_COEF8: rd_value = rd_coef8;
            ADDR_COEF9: rd_value = rd_coef9;
            ADDR_COEF10: rd_value = rd_coef10;
            ADDR_COEF11: rd_value = rd_coef11;
            ADDR_COEF12: rd_value = rd_coef12;
            ADDR_COEF13: rd_value = rd_coef13;
            ADDR_COEF14: rd_value = rd_coef14;
            ADDR_COEF15: rd_value = rd_coef15;
            ADDR_SCRATCH: rd_value = rd_scratch;
            ADDR_ERR_ADDR: rd_value = rd_err_addr;
            ADDR_ERR_STATUS: rd_value = rd_err_status;
            default: begin rd_value = 32'h0; rd_hit = 1'b0; end
        endcase
    end
    assign s_axil_arready = !s_axil_rvalid;
    always_ff @(posedge aclk) begin
        if (!aresetn) begin
            s_axil_rvalid <= 1'b0;
            s_axil_rdata <= 32'h0;
            s_axil_rresp <= RESP_OKAY;
        end else if (s_axil_arvalid && s_axil_arready) begin
            s_axil_rvalid <= 1'b1;
            s_axil_rdata <= rd_value;
            s_axil_rresp <= rd_hit ? RESP_OKAY : RESP_UNMAPPED_RD;
        end else if (s_axil_rvalid && s_axil_rready) begin
            s_axil_rvalid <= 1'b0;
        end
    end

    // ---- error capture: every access to an unmapped address is recorded (ERR_ADDR, ERR_STATUS) ----
    // The first one since the last clear sets STICKY and is kept; later ones only add to COUNT (saturating).
    // A write of 1 to STICKY clears the record; a bad access in the clock of that clear is not lost: it starts
    // the new record. A bad read and a bad write in the same clock count 2 and the read is the one recorded.
    assign ecap_bad_wr = wr_commit && !wr_hit;
    assign ecap_bad_rd = s_axil_arvalid && s_axil_arready && !rd_hit;
    assign ecap_clr    = wr_err_status && w_data[0] && w_bits[0];
    assign ecap_first  = ecap_clr || !ecap_sticky;
    assign ecap_sum = {1'b0, ecap_clr ? 8'h0 : ecap_count} + {8'h0, ecap_bad_rd} + {8'h0, ecap_bad_wr};
    always_ff @(posedge aclk) begin
        if (!aresetn) begin
            ecap_sticky <= 1'b0;
            ecap_is_write <= 1'b0;
            ecap_addr <= 12'h0;
            ecap_count <= 8'h0;
        end else if (ecap_bad_rd || ecap_bad_wr) begin
            ecap_sticky <= 1'b1;
            ecap_count <= ecap_sum[8] ? {8{1'b1}} : ecap_sum[7:0];
            if (ecap_first) begin
                ecap_addr <= ecap_bad_rd ? {s_axil_araddr[11:2], 2'b00} : {aw_word, 2'b00};
                ecap_is_write <= !ecap_bad_rd;
            end
        end else if (ecap_clr) begin
            ecap_sticky <= 1'b0;
            ecap_count <= 8'h0;
        end
    end

    // AxPROT is accepted and not used; the unused address bits [1:0] are word-aligned by the protocol
    logic unused_ok;
    assign unused_ok = ^{s_axil_awprot, s_axil_arprot, s_axil_awaddr[1:0], s_axil_araddr[1:0]};
endmodule
